function buildAdjList(edges) {
  const graph = {};
  for (const [u, v] of edges) {
    if (!graph[u]) graph[u] = [];
    if (!graph[v]) graph[v] = [];
    graph[u].push(v);
    graph[v].push(u); // remove for directed graph
  }
  return graph;
}

// Usage
const edges = [[0,1],[0,2],[1,3],[2,3]];
const graph = buildAdjList(edges);
// { '0': [1,2], '1': [0,3], '2': [0,3], '3': [1,2] }

function buildAdjListMap(edges) {
  const graph = new Map();
  for (const [u, v] of edges) {
    if (!graph.has(u)) graph.set(u, []);
    if (!graph.has(v)) graph.set(v, []);
    graph.get(u).push(v);
    graph.get(v).push(u);
  }
  return graph;
}

// Works with any node type:
const edges = [[{id:1}, {id:2}], [{id:1}, {id:3}]];
const graph = buildAdjListMap(edges);

function countConnectedComponents(n, edges) {
  const graph = buildAdjList(edges);
  const visited = new Set();
  let count = 0;

  function dfs(node) {
    visited.add(node);
    for (const neighbor of graph[node] || []) {
      if (!visited.has(neighbor)) dfs(neighbor);
    }
  }

  for (let i = 0; i < n; i++) {
    if (!visited.has(i)) {
      dfs(i);
      count++;
    }
  }
  return count;
}

