function numIslandsBFS(grid) {
  if (!grid.length) return 0;
  const rows = grid.length;
  const cols = grid[0].length;
  let count = 0;
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== '1') continue;
      count++;
      const queue = [[r, c]];
      grid[r][c] = '0';

      while (queue.length) {
        const [cr, cc] = queue.shift();
        for (const [dr, dc] of dirs) {
          const nr = cr + dr;
          const nc = cc + dc;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === '1') {
            queue.push([nr, nc]);
            grid[nr][nc] = '0';
          }
        }
      }
    }
  }
  return count;
}

function cloneGraph(node) {
  if (!node) return null;

  const map = new Map();
  map.set(node, { val: node.val, neighbors: [] });
  const queue = [node];

  while (queue.length) {
    const current = queue.shift();
    for (const neighbor of current.neighbors) {
      if (!map.has(neighbor)) {
        map.set(neighbor, { val: neighbor.val, neighbors: [] });
        queue.push(neighbor);
      }
      map.get(current).neighbors.push(map.get(neighbor));
    }
  }
  return map.get(node);
}

function cloneGraphDFS(node, map = new Map()) {
  if (!node) return null;
  if (map.has(node)) return map.get(node);

  const clone = { val: node.val, neighbors: [] };
  map.set(node, clone);

  for (const neighbor of node.neighbors) {
    clone.neighbors.push(cloneGraphDFS(neighbor, map));
  }
  return clone;
}

function canFinish(numCourses, prerequisites) {
  const graph = {};
  const inDegree = new Array(numCourses).fill(0);

  for (const [course, prereq] of prerequisites) {
    if (!graph[prereq]) graph[prereq] = [];
    graph[prereq].push(course);
    inDegree[course]++;
  }

  const queue = [];
  for (let i = 0; i < numCourses; i++) {
    if (inDegree[i] === 0) queue.push(i);
  }

  let processed = 0;
  while (queue.length) {
    const course = queue.shift();
    processed++;
    for (const next of graph[course] || []) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return processed === numCourses;
}

// Returns true if no cycle exists

function canFinishDFS(numCourses, prerequisites) {
  const graph = {};
  for (const [c, p] of prerequisites) {
    if (!graph[p]) graph[p] = [];
    graph[p].push(c);
  }

  const visited = new Set();   // fully processed
  const visiting = new Set();  // in current recursion stack

  function dfs(node) {
    if (visiting.has(node)) return false; // cycle found
    if (visited.has(node)) return true;
    visiting.add(node);

    for (const neighbor of graph[node] || []) {
      if (!dfs(neighbor)) return false;
    }

    visiting.delete(node);
    visited.add(node);
    return true;
  }

  for (let i = 0; i < numCourses; i++) {
    if (!dfs(i)) return false;
  }
  return true;
}

function ladderLength(beginWord, endWord, wordList) {
  if (!wordList.includes(endWord)) return 0;
  const wordSet = new Set(wordList);
  const queue = [[beginWord, 1]];
  const visited = new Set([beginWord]);

  while (queue.length) {
    const [word, level] = queue.shift();
    if (word === endWord) return level;

    for (let i = 0; i < word.length; i++) {
      for (let c = 97; c <= 122; c++) {
        const newWord = word.slice(0, i) + String.fromCharCode(c) + word.slice(i + 1);
        if (wordSet.has(newWord) && !visited.has(newWord)) {
          visited.add(newWord);
          queue.push([newWord, level + 1]);
        }
      }
    }
  }
  return 0;
}

